import {handle as directHandle} from './engine.js';
import {reconcileMessages, destination, addressKey} from './core.js';

const $=id=>document.getElementById(id);
const paths={messages:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z',phone:'M8 2h8a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Zm3 16h2',download:'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',compose:'M15 4 20 9M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14v6Z',chevron:'m9 5 7 7-7 7',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 2M4 17l2 2a7 7 0 0 0 12-2',lock:'M6 10h12v11H6V10Zm3 0V6a3 3 0 0 1 6 0v4',back:'m14 5-7 7 7 7',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',arrow:'M5 12h14m-6-6 6 6-6 6',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01',sim:'M9 3h8a2 2 0 0 1 2 2v16H5V7l4-4Zm0 8h6v6H9v-6Z',close:'m6 6 12 12M6 18 18 6'};
document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[el.dataset.icon]||paths.messages}"/></svg>`});
const state={mode:localStorage.getItem('voiceish-route')||'direct',pairing:null,drafts:{},status:null,messages:[],sends:[],selected:null,demo:false,online:false,refreshing:false,names:{},demoDrafts:{},emptyThreads:[],sending:false};
let toastTimer,installEvent,draftTimer;
const toast=text=>{clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4200)};
const showError=error=>{$('notice').textContent=error.message||String(error);$('notice').hidden=false};
const clearError=()=>{$('notice').hidden=true};
function extensionCall(message,timeout=15000){return new Promise((resolve,reject)=>{const id=crypto.randomUUID();const listener=e=>{if(e.source!==window||e.origin!==location.origin||e.data?.channel!=='voiceish-extension-response'||e.data.id!==id)return;cleanup();e.data.ok?resolve(e.data.data):reject(new Error(e.data.error||'Extension request failed.'))};const timer=setTimeout(()=>{cleanup();reject(new Error('Voiceish extension was not found. Install the updated extension, pair in its popup, then reload this page.'))},timeout);function cleanup(){clearTimeout(timer);window.removeEventListener('message',listener)}window.addEventListener('message',listener);window.postMessage({channel:'voiceish-web-request',id,message},location.origin)})}
async function call(message){return state.mode==='extension'?extensionCall(message):directHandle(message)}
function chooseRoute(route){if(state.mode!==route){state.pairing=null;state.status=null;state.drafts={};state.messages=[];state.sends=[];state.selected=null;state.online=false;state.emptyThreads=[];$('message').value='';clearError()}state.mode=route;localStorage.setItem('voiceish-route',route);$('direct-route').classList.toggle('selected',route==='direct');$('extension-route').classList.toggle('selected',route==='extension');$('direct-setup').hidden=route!=='direct';$('extension-setup').hidden=route!=='extension';$('route-label').textContent=route==='direct'?'Direct connection':'Chrome extension'}
function label(address){return state.demo?(state.names[address]||address):address}
function initials(address){const name=label(address);return /[a-z]/i.test(name)?name.split(' ').map(x=>x[0]).slice(0,2).join(''):name.slice(-2)}
const time=d=>new Date(d).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});
const day=d=>new Date(d).toLocaleDateString([],{month:'long',day:'numeric',year:'numeric'});
function allMessages(){return reconcileMessages(state.messages,state.sends)}
function groups(){const result=new Map();for(const m of allMessages()){const address=addressKey(m.address);if(!result.has(address))result.set(address,[]);result.get(address).push(m)}for(const a of state.emptyThreads)if(!result.has(a))result.set(a,[]);return [...result.entries()].sort((a,b)=>(b[1].at(-1)?.date||Date.now())-(a[1].at(-1)?.date||Date.now()))}
function renderThreads(){const list=$('threads');list.replaceChildren();let entries=groups();$('count').textContent=entries.length;const query=$('search').value.trim().toLowerCase();entries=entries.filter(([a,ms])=>label(a).toLowerCase().includes(query)||a.includes(query)||ms.some(m=>m.body.toLowerCase().includes(query)));if(!entries.length){const p=document.createElement('p');p.className='empty-list';p.textContent=query?'No conversations match your search.':state.pairing?'No conversations yet. Start a new message with the compose button.':'Your conversations will appear here once you connect your phone.';list.append(p);if(!state.pairing){const b=document.createElement('button');b.className='text-button';b.textContent='Explore a demo conversation';b.onclick=enterDemo;list.append(b)}return}for(const [address,ms]of entries){const latest=ms.at(-1);const b=document.createElement('button');b.className='thread'+(state.selected===address?' selected':'');b.setAttribute('aria-label',`Open conversation with ${label(address)}`);const avatar=document.createElement('span');avatar.className='avatar';avatar.textContent=initials(address);const content=document.createElement('div');content.style.minWidth='0';const top=document.createElement('div');top.className='thread-top';const name=document.createElement('span');name.className='thread-name';name.textContent=label(address);const clock=document.createElement('span');clock.className='thread-time';clock.textContent=latest?time(latest.date):'New';top.append(name,clock);const preview=document.createElement('p');preview.className='thread-preview';preview.textContent=latest?`${latest.type==='out'?'You: ':''}${latest.body}`:'Write the first message';content.append(top,preview);b.append(avatar,content);b.onclick=()=>select(address);list.append(b)}}
function renderStatus(){const paired=!!state.pairing;const demo=state.demo;$('device-name').textContent=demo?'Demo phone':state.pairing?.device||'Connect your phone';$('device-state').textContent=demo?'Sample messages only':state.online?`${state.status?.sim?.label||'Default SIM'} · Connected`:paired?'Paired · not connected':'Your SIM. Your number.';$('connection-chip').textContent=demo?'Demo mode':state.online?'Connected':paired?'Offline':'Not connected';$('connection-chip').classList.toggle('connected',state.online&&!demo);$('demo-banner').hidden=!demo;$('setup-connected').hidden=!paired||demo;$('connected-description').textContent=paired?`Paired with ${state.pairing.device}. ${state.pairing.url}`:'';$('sim-label').textContent=demo?'Demo SIM · no real SMS':state.status?.sim?.label||'Default SMS SIM';$('route-label').textContent=demo?'Demo only':state.mode==='direct'?'Direct connection':'Chrome extension';$('refresh').disabled=state.refreshing||(!paired&&!demo);$('refresh').classList.toggle('busy',state.refreshing)}
function renderConversation(){const selected=state.selected;$('welcome').hidden=!!selected;$('messages').hidden=!selected;$('composer-region').hidden=!selected;if(!selected){$('conversation-title').textContent='A little more room to talk.';$('conversation-subtitle').textContent='Text from your phone, comfortably.';$('header-avatar').textContent='V';return}$('conversation-title').textContent=label(selected);$('conversation-subtitle').textContent=state.demo?`${selected} · Sample conversation`:'SMS · '+(state.status?.sim?.label||'Default SMS SIM');$('header-avatar').textContent=initials(selected);const target=$('messages');const nearBottom=$('message-area').scrollHeight-$('message-area').scrollTop-$('message-area').clientHeight<100;target.replaceChildren();let previousDay='';for(const m of allMessages().filter(m=>addressKey(m.address)===selected)){const currentDay=day(m.date);if(currentDay!==previousDay){const d=document.createElement('div');d.className='date-divider';d.textContent=currentDay;target.append(d);previousDay=currentDay}const row=document.createElement('div');row.className='message-row '+m.type;const bubble=document.createElement('div');bubble.className='bubble';bubble.textContent=m.body;const meta=document.createElement('div');meta.className='message-meta';meta.textContent=time(m.date)+(m.type==='out'?` · ${state.demo?'Demo':m.status==='sent'?'Sent to carrier':m.status==='sending'?'Sending':m.status==='unknown'?'Unconfirmed':m.status}`:'');if(m.error)meta.title=m.error;row.append(bubble,meta);target.append(row)}if(!target.childElementCount){const p=document.createElement('p');p.className='empty-list';p.textContent='This is the start of your conversation.';target.append(p)}const draft=state.demo?{text:state.demoDrafts[selected]||''}:state.drafts[selected];const attempt=draft?.attempt;$('send-warning').hidden=!attempt;if(attempt){$('send-warning').textContent=attempt.status==='sending'?'Waiting for the phone’s send receipt. Refresh to check.':`Send ${attempt.status}. ${attempt.error||'Check your phone before composing again.'}`;if(['unknown','failed'].includes(attempt.status)){const b=document.createElement('button');b.className='text-button';b.textContent='I checked — compose again';b.onclick=async()=>{if(!confirm('Check the phone first: this message may already have been sent. Compose a new attempt?'))return;try{Object.assign(state,await call({type:'compose-again',to:selected}));$('message').value=state.drafts[selected]?.text||'';renderConversation()}catch(e){showError(e)}};$('send-warning').append(b)}}$('message').disabled=!!attempt||state.sending;$('send').disabled=!!attempt||state.sending||(!state.demo&&(!state.online||!state.status?.sim?.ready||!state.status?.permissions?.sendSms));if(nearBottom)requestAnimationFrame(()=>$('message-area').scrollTop=$('message-area').scrollHeight);updateCount()}
function render(){renderStatus();renderThreads();renderConversation()}
async function persistDraft(address,text){if(!address)return;if(state.demo){state.demoDrafts[address]=text;return}try{const s=await call({type:'draft',to:address,text});state.drafts=s.drafts}catch(e){showError(e)}}
async function select(address){clearTimeout(draftTimer);if(state.selected&&(!state.drafts[state.selected]?.attempt||state.demo))await persistDraft(state.selected,$('message').value);state.selected=address;$('message').value=state.demo?state.demoDrafts[address]||'':state.drafts[address]?.text||'';document.querySelector('.workspace').classList.add('show-conversation');render();requestAnimationFrame(()=>$('message-area').scrollTop=$('message-area').scrollHeight)}
function updateCount(){$('char-count').textContent=`${$('message').value.length} / 2000`}
async function refresh(){if(state.demo){toast('You’re viewing sample messages.');return}if(state.refreshing)return;state.refreshing=true;renderStatus();try{const previousAttempt=state.drafts[state.selected]?.attempt;const data=await call({type:'refresh'});Object.assign(state,data);if(previousAttempt&&!state.drafts[state.selected]?.attempt)$('message').value=state.drafts[state.selected]?.text||'';state.online=true;clearError();if(state.selected&&!state.drafts[state.selected]?.attempt&&document.activeElement!==$('message'))$('message').value=state.drafts[state.selected]?.text||'';if(!state.status.permissions?.readSms)showError(new Error('Allow SMS access in the phone app to load conversations.'));if(!state.status.sim?.ready)showError(new Error(state.status.sim?.reason||'The phone’s SMS SIM is not ready.'))}catch(e){state.online=false;showError(e)}finally{state.refreshing=false;render()}}
function openSetup(){chooseRoute(state.mode);$('setup-error').textContent='';renderStatus();$('setup-dialog').showModal()}
async function exitDemo(){state.demo=false;state.names={};state.messages=[];state.sends=[];state.selected=null;state.emptyThreads=[];state.status=null;state.pairing=null;state.drafts={};state.online=false;$('message').value='';try{Object.assign(state,await call({type:'state'}))}catch{}render();if(state.pairing)refresh()}
function enterDemo(){state.demo=true;state.online=false;state.selected=null;state.pairing={device:'Demo phone',url:''};state.status={sim:{id:1,label:'Demo SIM',ready:true},permissions:{sendSms:true,readSms:true}};state.names={'+16135550142':'Camille Martin','+16135550187':'Alex Morgan','+16135550129':'Weekend plans'};const now=Date.now();const samples=[['+16135550142','in','Found that little café you mentioned. The one with the excellent window seats.',-38],['+16135550142','out','That’s the one! Their coffee is worth the detour.',-35],['+16135550187','in','I’ll bring the adapter when I stop by tomorrow.',-31],['+16135550129','in','Saturday morning works. Shall we take the scenic route?',-20],['+16135550142','in','Save me a seat? I can be there around two.',-12],['+16135550142','out','Absolutely. I’ll bring the book we were talking about.',-10],['+16135550142','in','Perfect. See you soon.',-8]];state.messages=samples.map(([address,type,body,offset],i)=>({id:`demo-${i}`,address,type,body,date:now+offset*60000,status:type==='out'?'sent':'received',subscriptionId:1}));state.sends=[];state.drafts={};state.emptyThreads=[];clearError();select('+16135550142')}
async function send(event){event.preventDefault();const address=state.selected,body=$('message').value;if(!address||!body.trim()||state.sending)return;if(state.demo){state.messages.push({id:crypto.randomUUID(),address,body,type:'out',status:'sent',date:Date.now(),subscriptionId:1});state.demoDrafts[address]='';$('message').value='';render();toast('Demo message added. No SMS was sent.');return}if(!state.online||!state.status?.sim?.ready)return;clearTimeout(draftTimer);state.sending=true;renderConversation();try{const result=await call({type:'send',params:{sendId:crypto.randomUUID(),to:address,body,subscriptionId:state.status.sim.id}});state.drafts=result.drafts;if(result.status==='sent'&&state.selected===address)$('message').value='';if(result.error)showError(new Error(result.error));await refresh()}catch(e){showError(e);try{const latest=await call({type:'state'});state.drafts=latest.drafts}catch{}}finally{state.sending=false;render()}}
$('composer').onsubmit=send;$('message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!$('send').disabled)send(e)}};$('message').oninput=()=>{updateCount();clearTimeout(draftTimer);const a=state.selected,t=$('message').value;draftTimer=setTimeout(()=>persistDraft(a,t),250)};$('search').oninput=renderThreads;$('refresh').onclick=refresh;$('back').onclick=()=>document.querySelector('.workspace').classList.remove('show-conversation');$('inbox-nav').onclick=()=>{document.querySelector('.workspace').classList.remove('show-conversation');if(!state.pairing&&!state.demo&&innerWidth>=768)openSetup()};['devices-nav','settings-nav','device-strip','connection-chip','connect-main'].forEach(id=>$(id).onclick=openSetup);$('demo').onclick=enterDemo;$('exit-demo').onclick=exitDemo;$('direct-route').onclick=()=>{chooseRoute('direct');render()};$('extension-route').onclick=()=>{chooseRoute('extension');render()};
$('pair-button').onclick=async()=>{const button=$('pair-button');button.disabled=true;$('setup-error').textContent='';try{if(state.demo)await exitDemo();chooseRoute('direct');const existing=await call({type:'state'});const result=existing.pairing?existing:await call({type:'pair',text:$('pairing-text').value});Object.assign(state,result);$('pairing-text').value='';await refresh();if(state.online){$('setup-dialog').close();toast('Phone paired. Your messages are ready.')}else $('setup-error').textContent='Pairing saved, but the phone is unreachable. Start the bridge, check Wi-Fi and allow local-network access if prompted. If your browser blocks the connection, use the Chrome extension option.'}catch(e){$('setup-error').textContent=e.message}finally{button.disabled=false;render()}};
$('extension-connect').onclick=async()=>{const b=$('extension-connect');b.disabled=true;$('setup-error').textContent='';try{if(state.demo)await exitDemo();chooseRoute('extension');state.selected=null;state.messages=[];state.sends=[];state.drafts={};state.status=null;state.online=false;state.pairing=null;Object.assign(state,await call({type:'state'}));if(!state.pairing)throw new Error('Open the Voiceish extension from Chrome’s toolbar and pair your phone there first.');await refresh();if(state.online){$('setup-dialog').close();toast('Connected through the extension.')}else throw new Error('The extension is available, but your phone is unreachable. Start its bridge and check Wi-Fi.')}catch(e){$('setup-error').textContent=e.message}finally{b.disabled=false;render()}};
$('forget-button').onclick=async()=>{if(!confirm('Forget this phone and clear its drafts in the selected connection method?'))return;try{await call({type:'forget'});state.pairing=null;state.status=null;state.drafts={};state.messages=[];state.sends=[];state.selected=null;state.online=false;state.emptyThreads=[];clearError();render();toast('Phone forgotten.')}catch(e){$('setup-error').textContent=e.message}};
$('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin);toast('Site link copied.')}catch{$('setup-error').textContent=`Open ${location.origin} on your phone.`}};
$('new-message').onclick=()=>{if(!state.pairing&&!state.demo){openSetup();return}$('recipient-error').textContent='';$('compose-dialog').showModal();$('recipient').focus()};$('close-compose').onclick=()=>$('compose-dialog').close();$('new-form').onsubmit=e=>{e.preventDefault();try{const a=destination($('recipient').value);if(!state.emptyThreads.includes(a))state.emptyThreads.push(a);$('compose-dialog').close();select(a)}catch(err){$('recipient-error').textContent=err.message}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('install-button').disabled=false});window.addEventListener('appinstalled',()=>{installEvent=null;toast('Voiceish is installed.')});$('install-nav').onclick=()=>{$('install-button').disabled=!installEvent;$('install-dialog').showModal()};$('install-button').onclick=async()=>{if(!installEvent)return;await installEvent.prompt();await installEvent.userChoice;installEvent=null;$('install-button').disabled=true};
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
chooseRoute(state.mode);render();try{Object.assign(state,await call({type:'state'}));render();if(state.pairing)refresh()}catch(e){showError(e)}
setInterval(()=>{if(!document.hidden&&!state.demo&&state.pairing&&!state.sending)refresh()},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.pairing&&!state.demo)refresh()});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
